INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3121, 'https://www.kfupm.edu.sa/study/international-students/fees-and-scholarships', 'Tuition costs and Scholarships - International Students | KFUPM (official)', 'kfupm.edu.sa', 'scholarship', now(), true, true, now()), (3122, 'https://www.kfupm.edu.sa/study/international-students/apply-as-an-international-student', 'Apply as an International Student | KFUPM (official)', 'kfupm.edu.sa', 'scholarship', now(), true, true, now());

-- 2. Record 608 (KFUPM undergraduate) uplift
UPDATE scholarships SET title = $$KFUPM International Undergraduate Scholarship$$, provider = $$King Fahd University of Petroleum & Minerals (KFUPM)$$, country = $$Saudi Arabia$$, coverage_type = $$Full Tuition + Stipend$$, amount_usd_value = 0, award_amount = NULL, award_currency = $$SAR$$, award_period = $$month$$, award_basis = $$variable$$, deadline = $$No application dates are published on the fetched KFUPM pages. Undergraduate admission tracks (the SAT track for local and international students, the Science Olympiad track, the primary/secondary tracks) open and close on the admissions portal apply.kfupm.edu.sa - every track showed as Closed when checked on 28 October 2026. Prepare your SAT score (1350+) and watch the portal for the SAT track reopening.$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[{"cycle": "Undergraduate SAT Admission track (local & international students, SAT 1350+)", "status": "shown as Closed on apply.kfupm.edu.sa at last check (2026-10-28); reopening dates are announced on the portal"}, {"pattern": "ISEF Winners Track - spaces are offered to the top four ISEF winners each year (guaranteed admission + full scholarship + free choice of major)"}]$$, recurrence = $$annual$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Bachelor's"]$$, eligible_majors = $$["KFUPM bachelor programmes across its colleges (Engineering & Physics; Computing and Mathematics; Petroleum Engineering & Geosciences; Chemicals and Materials; Design and Built Environment; Business School) - SAT-track applicants must come from a natural-sciences high-school track"]$$, eligible_countries = $$["International students living outside Saudi Arabia (KFUPM's full-scholarship scope for undergraduates); 87+ nationalities are represented in the student body"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$King Fahd University of Petroleum and Minerals states plainly on its international-students fees-and-scholarships page: "As an international student living outside Saudi Arabia, your tuition fees are waived. You will receive a full scholarship to attend KFUPM." The fetched page lists the undergraduate benefits: free on-campus housing in fully equipped dorms, complimentary course texts that are borrowed rather than bought, a monthly stipend (the amount is not published on the fetched pages), and medical services through the on-campus clinic. All courses are taught in English, and more than 87 nationalities are represented in the student body of this engineering, science and technology university in Dhahran. International undergraduates enter mainly through the SAT Track (international high-school graduate of the current or previous year, natural-sciences track, SAT 1350 or above, then a KFUPM math assessment by invitation) or the ISEF Winners Track (the top four ISEF winners each year receive guaranteed admission, a full scholarship and free choice of major). After acceptance, KFUPM handles the visa-issuing process. Note that the air-ticket and other richer benefits on the same fees page belong to the GRADUATE scholarships (record 454), not to this undergraduate award - earlier side-table text on this record wrongly imported "flights" and aggregator profile figures (GPA 3.7+, IELTS 6.0+, SAT 1450+) that KFUPM does not publish for these tracks.$$ , requirements = $$SAT Track (per the fetched Apply-as-an-International-Student page): graduate from an international high school (current or previous year); your studies should have a natural sciences focus/track; SAT score of 1350 or above, sent through College Board directly to KFUPM (select "King Fahd University of Petroleum and Minerals" when sending). After KFUPM verifies the SAT score you are invited to take the KFUPM math assessment; then complete the application through the Admission Website (apply.kfupm.edu.sa). After acceptance, KFUPM handles the visa-issuing process. ISEF Winners Track: high-school graduate (current or previous year) with a natural-sciences focus who is an ISEF award winner - spaces are offered to the top four winners each year, with guaranteed admission, a full scholarship and freedom to choose any major. The fetched undergraduate pages publish no GPA cut-off and no English-test minimum for these tracks (the IELTS/TOEFL/Duolingo minima on the same page belong to graduate admission - see record 454), so min_gpa and min_ielts are NULL; the SAT 1350 minimum is the published academic bar and is stated here textually.$$ , website_url = $$https://www.kfupm.edu.sa/study/international-students/fees-and-scholarships$$, source_url = $$https://www.kfupm.edu.sa/study/international-students/fees-and-scholarships$$, application_url = $$https://apply.kfupm.edu.sa/$$, funding_type = $$Full scholarship for international undergraduates living outside Saudi Arabia (KFUPM wording): tuition fees waived + free on-campus housing + complimentary borrowed course texts + monthly stipend (amount not published on the fetched pages) + medical services at the on-campus clinic.$$ , tuition_coverage = $$Tuition fees fully waived for international students living outside Saudi Arabia, with free housing, borrowed course texts, a monthly stipend and campus-clinic medical services on top. Air tickets are a graduate-scholarship benefit (record 454), not part of this undergraduate award on the fetched page.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = $$Free on-campus housing - fully equipped dorms near the classrooms (per KFUPM's fees-and-scholarships page).$$ , application_fee = NULL, english_requirements = $$All courses at KFUPM are taught in English. The fetched undergraduate track pages publish no English-test minimum for the SAT/ISEF tracks - the IELTS 6.0 / TOEFL iBT 70 / Duolingo 105 (Master's) and 6.5 / 80 / 120 (PhD) tables on KFUPM's international page apply to GRADUATE admission (record 454) and must not be read as undergraduate requirements. Check the application portal for any English evidence your track requests.$$ , required_documents = $$["SAT score of 1350 or above sent through College Board directly to KFUPM (SAT Track)", "International high-school certificate and transcripts - natural sciences track, graduated in the current or previous year", "KFUPM math assessment (by invitation, after SAT verification)", "Completed application on the KFUPM admissions portal (apply.kfupm.edu.sa)", "ISEF award documentation (ISEF Winners Track)", "Passport - KFUPM handles the visa-issuing process after acceptance"]$$, application_status = $$upcoming$$, verification_status = $$verified$$, source_reliability = 10, is_active = true, university_id = 69, notes = $$BATCH 25 UPLIFT 2026-10-28 (rel 8 -> 10): re-verified first-hand on the fetched KFUPM fees-and-scholarships page (new source 3121), the Apply-as-an-International-Student page (new source 3122) and the admissions portal landing (apply.kfupm.edu.sa, all UG tracks Closed at check). CORRECTIONS to the 2026-10-23 state: (1) min_gpa 3.7 and min_ielts 6.0 REMOVED - they came from a third-party guide (still quoted verbatim in us 67 before this batch) and from KFUPM's GRADUATE English table; the fetched UG tracks publish only SAT >= 1350 + natural-sciences high school (current/previous year). (2) deadline 2027-02-11/fixed REMOVED - no dates are published on the fetched pages and the portal shows the SAT track Closed; now NULL/not_published + rounds, status unknown -> upcoming (this lowers the future-deadline counter by 1). (3) The 'separate needs-and-merit scholarship (10-100%)' paragraph from the previous rewrite is not present on the fetched pages and was dropped as unverifiable. (4) degree_levels normalized Bachelor -> Bachelor's; accommodation/funding texts filled from the fetched benefits list; us 67 fully resynced (its 'Flights', 'SAT 1450+', 'automatic Full Ride candidacy' claims were aggregator text - air tickets are a graduate benefit per the same fetched page). The 2026-10-23 pass had already removed an invented USD 16,800 figure and the wrong Master's/PhD levels from this row.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 608;

-- 3. Record 673 (Stockholm University Scholarship Scheme) uplift
UPDATE scholarships SET title = $$Stockholm University Scholarship Scheme$$, provider = $$Stockholm University$$, country = $$Sweden$$, coverage_type = $$Tuition Waiver$$, amount_usd_value = 0, award_amount = NULL, award_currency = $$SEK$$, award_period = $$year$$, award_basis = $$variable$$, deadline = $$No advance scholarship application exists. Apply to an SU master's in the first (international) admission round via universityadmissions.se (mid-October to 15 January; documents and the SEK 900 fee by 1 February); after the Notification of Selection Results, eligible admitted students are emailed the scholarship form, and recipients are informed by the end of April.$$ , deadline_date = NULL, deadline_type = $$not_published$$, opening_date = NULL, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[{"cycle": "Autumn 2027 entry, first (international) admission round", "opens": "2026-10-16", "deadline": "2027-01-15 (programme application + ranking); documents and SEK 900 fee by 2027-02-01", "status": "admission round open; the scholarship form is emailed to eligible admitted students after the selection results, decisions by end of April 2027"}]$$, recurrence = $$annual$$, expected_opening_period = NULL, expected_deadline_period = NULL, degree_levels = $$["Master's"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["Citizens of countries outside the EU/EEA and Switzerland who are required to pay tuition fees and are admitted to a Stockholm University master's programme in the first (international) admission round"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$Stockholm University pays the whole tuition fee and nothing else, which makes it one of the cleaner offers in this cluster but also one of the easiest to misread. The Stockholm University Scholarship Scheme is aimed at especially qualified students and covers the whole tuition fee for a Master's programme at Stockholm University, and the university states explicitly that students will need to cover their living costs themselves. The fees it waives are published per field: SEK 90,000 a year in the humanities, social sciences and law, and SEK 140,000 a year in the sciences, with some programmes priced inside that range and a few joint programmes above it - so the waiver's value varies by programme and no single amount is stored. What makes this scheme unusual is the timing: there is no advance application. When the Notification of Selection Results is published, eligible students are sent an electronic application form to the email on their University Admissions account, and recipients are informed by the end of April. Eligibility is limited to citizens from outside the EU/EEA and Switzerland who must pay tuition fees and were admitted in the first (international) admission round; selection is based on academic merits (no published GPA or English cut-off), with priority to students who had Stockholm University as their first choice. The admission round itself runs mid-October to 15 January, with documents and the SEK 900 application fee due by 1 February, which means the student has to be ready to accept a place before the scholarship answer is final. Narrower related schemes have their own records: the Stockholm Trio Scholarship (982, two joint programmes) and the ICAL arbitration scholarships (983, 984); the Swedish Institute Scholarship for Global Professionals (922) is a separate full award restricted to a published country list.$$ , requirements = $$Be a citizen of a country outside the EU/EEA and Switzerland and therefore required to pay tuition fees, and be admitted to a Master's programme at Stockholm University in the first (international) admission round (apply via universityadmissions.se mid-October to 15 January; documents and the SEK 900 application fee by 1 February). There is no advance scholarship application and no published GPA or English-score cut-off: selection is based on the academic merits of the applicants, and priority is given to students with Stockholm University as their first choice on universityadmissions.se - so rank SU first. When the Notification of Selection Results is published, eligible students receive an electronic application form at the email address on their University Admissions account; scholarship recipients and other applicants are informed of the results by the end of April. Hold the finances for living costs independently, since the scheme covers tuition only and the university states this plainly. Note that the university offers no scholarships to EU/EEA or Swiss citizens.$$ , website_url = $$https://www.su.se/english/education/how-to-apply/costs-fees-and-scholarships/scholarships$$, source_url = $$https://www.su.se/english/education/how-to-apply/costs-fees-and-scholarships/scholarships$$, application_url = $$https://www.universityadmissions.se/$$, funding_type = $$Merit-based tuition fee waiver$$, tuition_coverage = $$The whole tuition fee for a master programme: SEK 90,000 a year in the humanities, social sciences and law and SEK 140,000 a year in the sciences, with some programmes priced inside that range and joint programmes above it. Living costs are explicitly not covered.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = $$Not covered - the scheme pays the tuition fee only; students cover their living costs themselves (per Stockholm University).$$ , application_fee = NULL, english_requirements = $$The scholarship sets no separate English score; the English requirement of the chosen master programme applies (evidenced through University Admissions).$$ , required_documents = $$["Master application through universityadmissions.se in the first admission round (mid-October to 15 January)", "Documents uploaded and SEK 900 application fee paid by 1 February", "Bachelor's degree certificate and transcripts (programme-specific requirements per University Admissions)", "Proof of English proficiency meeting the chosen programme's requirement", "The electronic scholarship form emailed to eligible admitted students after the Notification of Selection Results (no advance application exists)"]$$, application_status = $$upcoming$$, verification_status = $$verified$$, source_reliability = 10, is_active = true, university_id = 140, notes = $$BATCH 25 UPLIFT 2026-10-28 (rel 9 -> 10): re-verified first-hand on the fetched SU scholarships page (source 2623, page updated 2025-10-20), which confirms the 2026-10-25 rewrite's substance: whole tuition fee covered, living costs excluded, citizens outside EU/EEA/Switzerland admitted in the first (international) round, selection on academic merits with first-choice priority, electronic form emailed after the Notification of Selection Results, decisions by end of April. ENCODING CORRECTIONS: (1) award_amount SEK 140,000/'fixed' -> NULL/'variable' - the waived fee varies by field (90,000 vs 140,000 per year, verified 2026-10-25 on SU's costs page), so the previous notes' shortcut ('carries the higher published fee') is replaced by the house variable-amount encoding; (2) min_gpa 3.3 / min_ielts 6.5 REMOVED - the fetched page publishes no cut-offs (merit-based selection; English per programme); (3) eligible_countries 'All' -> the actual non-EU/EEA/Swiss fee-paying scope; (4) deadline_type 'annual' -> 'not_published' with the dated first-round cycle in rounds (status stays upcoming, as for records 983/984); (5) source link (673, 2623) added - the row previously had none; us 134 resynced. Prior history kept from the 2026-10-25 rewrite: invented USD 12,000 removed, master-only, no-advance-application model; SEK 5,000 repayment-fee detail from that verification remains in git history.$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 673;

-- 4. university_scholarships resyncs
UPDATE university_scholarships SET scholarship_name = $$KFUPM International Undergraduate Scholarship$$, availability_status = $$available$$, funding_type = $$Full scholarship for international students living outside Saudi Arabia: tuition waived + free housing + monthly stipend + campus-clinic medical services$$, max_scholarship = $$Tuition waived + free on-campus dorm + borrowed course texts + monthly stipend (amount not published)$$, covers_tuition = true, covers_living_expenses = true, valued_aspect = $$English-medium STEM bachelor's in Dhahran with a full ride for international students living outside Saudi Arabia; entry mainly via the SAT track (1350+)$$, eligibility_notes = $$SAT Track: international high-school graduate (current or previous year), natural-sciences track, SAT 1350+ sent via College Board, then KFUPM math assessment by invitation; visa handled by KFUPM after acceptance. ISEF Winners Track: top four ISEF winners yearly - guaranteed admission + full scholarship. No GPA/IELTS cut-offs are published for these undergraduate tracks (the IELTS/TOEFL tables on KFUPM's site are for graduate admission); tracks open/close on apply.kfupm.edu.sa.$$ , official_url = $$https://www.kfupm.edu.sa/study/international-students/fees-and-scholarships$$, source_url = $$https://www.kfupm.edu.sa/study/international-students/fees-and-scholarships$$, verification_status = $$verified_official_source$$, last_verified_at = now() WHERE id = 67;

UPDATE university_scholarships SET scholarship_name = $$Stockholm University Scholarship Scheme$$, availability_status = $$available$$, funding_type = $$Merit-based tuition fee waiver$$, max_scholarship = $$The whole tuition fee: SEK 90,000 or 140,000 a year depending on field (living costs not covered)$$, covers_tuition = true, covers_living_expenses = false, valued_aspect = $$Full tuition waiver for especially qualified fee-paying master students; no advance application - the form is emailed after admission results$$, eligibility_notes = $$Master level only: citizens outside the EU/EEA and Switzerland who pay tuition fees and are admitted in the first (international) admission round (apply mid-October-15 January; documents + SEK 900 fee by 1 February). Selection on academic merits (no published GPA/English cut-off), priority if SU was ranked first. The scholarship form is emailed after the Notification of Selection Results; decisions by end of April. Living costs are not covered.$$ , official_url = $$https://www.su.se/english/education/how-to-apply/costs-fees-and-scholarships/scholarships$$, source_url = $$https://www.su.se/english/education/how-to-apply/costs-fees-and-scholarships/scholarships$$, verification_status = $$verified_official_source$$, last_verified_at = now() WHERE id = 134;

